import RNA, random, time, multiprocessing as mp
unit_target = "(((((((....))(((((((((...))))..((((...)))))))))((....)))))))"
L=len(unit_target)

def worker(seed):
    random.seed(seed)
    for _ in range(50):
        start=''.join(random.choice('ACGU') for _ in range(L))
        seq,d = RNA.inverse_fold(start, unit_target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==unit_target:
            return seq
    return None

if __name__=='__main__':
    sols=set()
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, range(800)):
            if r:
                sols.add(r)
                if len(sols)>=10: 
                    p.terminate(); break
    print('distinct', len(sols))
    for s in sols: print(s)
EOF
